null,"requires":[],"scopes":["global"],"sensitivity":"normal","source":null,"type":"int","values":null,"workspaces":["client","contractor"]},{"conditions":[],"default":20,"delegable":false,"effect":"live","family":"value","implemented":true,"key":"messaging.max_per_minute","less_than":null,"max":60,"min":5,"min_items":null,"owner_choice":null,"requires":[],"scopes":["global"],"sensitivity":"sensitive","source":null,"type":"int","values":null,"workspaces":["client","contractor","staff"]},{"conditions":[],"default":20,"delegable":false,"effect":"prospective","family":"value","implemented":true,"key":"uploads.max_file_mb","less_than":null,"max":20,"min":1,"min_items":null,"owner_choice":null,"requires":[],"scopes":["global"],"sensitivity":"sensitive","source":null,"type":"int","values":null,"workspaces":["client","contractor","staff"]},{"conditions":[],"default":30,"delegable":false,"effect":"prospective","family":"value","implemented":true,"key":"reviews.response_edit_days","less_than":null,"max":90,"min":0,"min_items":null,"owner_choice":null,"requires":[],"scopes":["global"],"sensitivity":"normal","source":null,"type":"int","values":null,"workspaces":["contractor"]},{"conditions":[],"default":true,"delegable":false,"effect":"prospective","family":"catalog","implemented":true,"key":"catalog.trades.active","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":["global"],"sensitivity":"sensitive","source":"public.trades.active","type":"boolean","values":null,"workspaces":["staff"]},{"conditions":[],"default":"client","delegable":false,"effect":"live","family":"federated","implemented":true,"key":"pref.workspace","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":[],"sensitivity":"normal","source":"public.profiles.last_workspace","type":"enum","values":["client","contractor"],"workspaces":["client","contractor"]},{"conditions":[],"default":true,"delegable":false,"effect":"live","family":"federated","implemented":true,"key":"pref.notify.invitation_expiring","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":[],"sensitivity":"normal","source":"public.notification_preferences.invitation_expiring","type":"boolean","values":null,"workspaces":["client","contractor"]},{"conditions":[],"default":false,"delegable":false,"effect":"live","family":"federated","implemented":true,"key":"pref.contractor.counter_offers_optin","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":[],"sensitivity":"normal","source":"public.contractor_profiles.allow_counter_offers","type":"boolean","values":null,"workspaces":["contractor"]},{"conditions":[],"default":{"email":false,"exact_address":false,"phone":false,"social_links":false,"website":false,"whatsapp":false},"delegable":false,"effect":"live","family":"federated","implemented":true,"key":"pref.contractor.contact_visibility","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":[],"sensitivity":"normal","source":"public.contractor_profile_details.show_*","type":"flags","values":["website","phone","whatsapp","email","social_links","exact_address"],"workspaces":["contractor"]},{"conditions":[],"default":false,"delegable":false,"effect":"live","family":"federated","implemented":true,"key":"project.contract_enabled","less_than":null,"max":null,"min":null,"min_items":null,"owner_choice":null,"requires":[],"scopes":[],"sensitivity":"normal","source":"public.project_contract_settings.enabled","type":"boolean","values":null,"workspaces":["client"]}]'::jsonb);
